private theorem antitoneOn_variation_le (f : ℝ → ℝ) (S : Set ℝ) (C : ℝ)
    (hf : AntitoneOn f S) (hf0 : ∀ w ∈ S, 0 ≤ f w) (hfC : ∀ w ∈ S, f w ≤ C) :
    eVariationOn f S ≤ ENNReal.ofReal C

private theorem monotoneOn_variation_le (f : ℝ → ℝ) (S : Set ℝ) (C : ℝ)
    (hf : MonotoneOn f S) (hf0 : ∀ w ∈ S, 0 ≤ f w) (hfC : ∀ w ∈ S, f w ≤ C) :
    eVariationOn f S ≤ ENNReal.ofReal C

def initialDoubleObservable {n : ℕ}
    (nu : Measure BridgeNoise) (x : ℝ) (a : Shao.Path n) : ℝ :=
  if Shao.energy a = 0 then 1
  else doubleCompletion nu x (Shao.C1.normalizedEndpoint a)

def brownianInitialDouble {Ω : Type*}
    (B : ℝ≥0 → Ω → ℝ) (x : ℝ) : Set Ω :=
  {omega | (∃ t : BridgeTime, x ≤ B ⟨(t : ℝ), t.property.1⟩ omega) ∧
    (∃ t : BridgeTime, B ⟨(t : ℝ), t.property.1⟩ omega ≤ -x)}

def doubleCrossingEvent {n : ℕ} (x : ℝ) : Set (Shao.Path n) :=
  {a | (∃ r : ℕ, r ≤ n ∧ actualWall a x ≤ Shao.prefixSum a r) ∧
    (∃ r : ℕ, r ≤ n ∧ Shao.prefixSum a r ≤ -actualWall a x)}
